<?php defined('BASEPATH') or exit('No direct script access allowed');$c=$context;$ins=$c['installment']??['is_installment'=>false];$addr=trim(implode('، ',array_filter([$c['address']??'',$c['city']??'',$c['state']??'',$c['zip']??''])));?><!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><title>حواله خروج از انبار - فاکتور <?php echo html_escape($invoice->number);?></title><style>body{font-family:Tahoma,Arial,sans-serif;color:#111;margin:28px;direction:rtl}h1{font-size:22px;margin:0}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #111;padding-bottom:14px}.meta,.finance{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.box{border:1px solid #bbb;border-radius:8px;padding:10px}.box small{display:block;color:#666;margin-bottom:5px}table{width:100%;border-collapse:collapse;margin-top:14px}th,td{border:1px solid #aaa;padding:8px;text-align:right}th{background:#f2f2f2}.sign{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin-top:55px}.sign div{text-align:center;border-top:1px solid #333;padding-top:10px}.note{background:#f7f7f7;border:1px solid #ccc;padding:10px;margin-top:16px}.no-print{margin-bottom:18px}@media print{.no-print{display:none}body{margin:10mm}.box{break-inside:avoid}}</style></head><body><div class="no-print"><button onclick="window.print()">چاپ حواله خروج</button></div><div class="head"><div><h1>حواله خروج از انبار</h1><div>فاکتور شماره <?php echo html_escape($invoice->number);?></div></div><div>شماره حواله: <b><?php echo html_escape($delivery['goods_delivery_code']??$delivery['id']);?></b><br>تاریخ خروج: <b><?php echo html_escape($delivery['display_date']??'-');?></b></div></div>
<div class="meta"><div class="box"><small>مشتری</small><b><?php echo html_escape($c['company']??'-');?></b></div><div class="box"><small>شماره تماس</small><b><?php echo html_escape($c['phonenumber']??'-');?></b></div><div class="box"><small>تاریخ فاکتور</small><b><?php echo html_escape($c['display_date']??'-');?></b></div></div><div class="box"><small>نشانی تحویل</small><?php echo html_escape($addr?:'-');?></div>
<h3>اقلام خروجی</h3><table><thead><tr><th>ردیف</th><th>شرح کالا</th><th>محل کالا</th><th>تعداد</th><th>قیمت واحد</th><th>تخفیف</th><th>مبلغ ردیف</th></tr></thead><tbody><?php $n=0;foreach(($c['items']??[]) as $it){$n++;?><tr><td><?php echo $n;?></td><td><?php echo html_escape($it['description']??'');?></td><td><?php echo html_escape($item_locations[(int)($it['id']??0)]??'—');?></td><td><?php echo html_escape($it['qty']??'');?></td><td><?php echo app_format_money($it['rate']??0,'');?></td><td><?php echo ($it['discount_amount_value']??0)>0?app_format_money($it['discount_amount_value'],''):'—';?></td><td><?php echo app_format_money($it['line_total']??0,'');?></td></tr><?php }?></tbody></table>
<h3>وضعیت تسویه حساب</h3><div class="finance"><div class="box"><small>مبلغ کل فاکتور</small><b><?php echo app_format_money($c['total']??0,'');?></b></div><div class="box"><small>پرداخت‌شده</small><b><?php echo app_format_money($c['paid']??0,'');?></b></div><div class="box"><small>مانده</small><b><?php echo app_format_money($c['remaining']??0,'');?></b></div></div><div class="box"><small>وضعیت</small><b><?php echo html_escape($c['payment_state']??'-');?></b><?php if(!empty($ins['is_installment'])){?> — اقساطی؛ پیش‌پرداخت <?php echo app_format_money($ins['down_payment'],'');?>؛ <?php echo (int)$ins['installment_count'];?> قسط؛ <?php echo (int)$ins['paid_installment_count'];?> قسط پرداخت شده<?php }?></div>
<?php if(!empty($ins['is_installment'])){?><table><thead><tr><th>قسط</th><th>سررسید</th><th>مبلغ</th><th>پرداخت‌شده</th><th>وضعیت</th></tr></thead><tbody><?php foreach($ins['installments'] as $ln){?><tr><td><?php echo (int)$ln['sequence_no'];?></td><td><?php echo html_escape($ln['display_due_date']);?></td><td><?php echo app_format_money($ln['amount'],'');?></td><td><?php echo app_format_money($ln['paid_amount'],'');?></td><td><?php echo ($ln['status']==='paid')?'پرداخت‌شده':(($ln['status']==='partial')?'جزئی':'در انتظار');?></td></tr><?php }?></tbody></table><?php }?>
<div class="note"><b>مجوز خروج:</b> صادر شده &nbsp; | &nbsp; تاریخ مجوز: <?php echo html_escape($permit['permit_date']??$c['display_date']??'-');?><?php if(!empty($permit['note'])){?><br><b>توضیحات:</b> <?php echo nl2br(html_escape($permit['note']));?><?php }?></div><div class="sign"><div>امضاء مدیر فروشگاه</div><div>امضاء حسابدار</div><div>امضاء انباردار</div></div></body></html>
